query:
Assume \eqref{eq:response_def}. Show that to leading order in the response,
\begin{equation}
\mathrm{Cov}_{\rm SSC}(O_i,O_j)= O_i'\,O_j'\,\sigma_b^2,
\qquad
\sigma_b^2\equiv \mathrm{Var}(\delta_b).
\label{eq:SSC_rank1}
\end{equation}
Then specialize to the bandpowers \eqref{eq:P_response} and show
\begin{equation}
\mathrm{Cov}_{\rm SSC}\big(\widehat P(k_i),\widehat P(k_j)\big)
= R(k_i)P(k_i)\,R(k_j)P(k_j)\,\sigma_b^2.
\label{eq:SSC_Pk}
\end{equation}

Take a Gaussian window
\begin{equation}
W(\mathbf{x})=\exp\!\left(-\frac{|\mathbf{x}|^2}{2R^2}\right),
\qquad R>0.
\label{eq:W_gauss}
\end{equation}
Show that
\begin{equation}
\frac{|\widetilde W(\mathbf{k})|^2}{|\widetilde W(\mathbf{0})|^2}=\exp(-R^2 k^2),
\label{eq:Wratio}
\end{equation}
and hence
\begin{equation}
\sigma_b^2=\int\frac{d^3q}{(2\pi)^3}\,P(q)\,e^{-R^2 q^2}.
\label{eq:sigma_general}
\end{equation}
Now assume a toy power spectrum
\begin{equation}
P(q)=A\,e^{-q^2/q_0^2},\qquad A>0,\ q_0>0,
\label{eq:Ptoy_n0}
\end{equation}
and compute $\sigma_b^2$ in closed form.
